  "settings.security.changeEmailTitle": "เปลี่ยนอีเมลบัญชีของคุณ",
  "settings.security.changeEmailDesc": "ย้ายบัญชีของคุณไปยังอีเมลใหม่ ร้านของคุณ สินค้าคงคลัง ทีม และประวัติจะย้ายตามไปด้วย — และจะไม่มีการทดลองใช้ฟรีใหม่เริ่มต้น อุปกรณ์อื่นทุกเครื่องที่เข้าสู่ระบบอยู่จะถูกออกจากระบบ",
