  "support.categoryLabel": "เรื่องนี้เกี่ยวกับอะไร",
  "support.contextNote": "เพื่อให้เราค้นหาปัญหาได้ โน้ตของคุณจะรวมหน้าเว็บที่คุณอยู่ ธุรกิจและบทบาทของคุณหากเลือกไว้ แผนของคุณ ภาษาแอปของคุณ และประเภทโทรศัพท์หรือเบราว์เซอร์ที่คุณใช้โดยอัตโนมัติ จะไม่รวมสินค้า สต็อก หรือยอดขายของคุณเลย",
  "support.description": "มีอะไรเสีย มีอะไรดูผิดปกติ หรือมีไอเดียจะแบ่งปันใช่ไหม บอกเราที่นี่ — โน้ตของคุณจะตรงไปยังทีมที่อยู่เบื้องหลังแอป",
