  "pricing.sectionTitle": "ราคาลด",
  "pricing.startLabel": "เริ่ม",
  "training.lessons.mgr-pricing.step1": "ใน Business แบบฟอร์มสินค้ามีส่วน ราคาลด โละสต็อกคือการปรับลดถาวร — ตั้งแล้วมันจะคงอยู่ โรลล์แบ็กคือเซลล์ที่มีวันที่: ตั้งราคาโรลล์แบ็ก วันเริ่ม และวันสิ้นสุด",
  "training.lessons.mgr-pricing.step2": "คุณไม่ต้องพิมพ์ราคาปกติซ้ำเลย: มันคงอยู่บนสินค้าและปรากฏข้างราคาลดในรายการสินค้าและในเครื่องสแกน เพื่อให้ทุกคนเห็นว่าสินค้าชิ้นนั้นปกติราคาเท่าไร",
  "training.lessons.mgr-pricing.step3": "พิมพ์ป้ายราคาใหม่เมื่อโรลล์แบ็กเริ่ม — ป้ายจะพิมพ์ราคาที่ลูกค้าจ่ายในวันนั้น เมื่อผ่านวันสิ้นสุดไปแล้ว ราคาจะกลับเป็นราคาปกติโดยอัตโนมัติ พิมพ์ป้ายราคาปกติอีกครั้งเมื่อคุณจัดชั้นวางใหม่",
  "training.lessons.mgr-pricing.step4": "ถ้าส่วน ราคาลด ดูเหมือนถูกล็อก แสดงว่าธุรกิจนั้นไม่ได้อยู่ในแพ็กเกจ Business — ราคาลดเป็นของแพ็กเกจนั้น และเจ้าของคือผู้ที่เปลี่ยนแพ็กเกจ",
  "training.lessons.mgr-pricing.title": "การจัดเซลล์: โละสต็อกและโรลล์แบ็ก",
  "training.lessons.owner-pricing.step1": "การปรับลดสองแบบอยู่ในแบบฟอร์มสินค้า ภายใต้หัวข้อ ราคาลด โละสต็อกเป็นแบบถาวร: ตั้งราคาโละสต็อกแล้วมันจะคงต่ำอยู่จนกว่าคุณจะเปลี่ยนกลับ โรลล์แบ็กคือการลดราคาชั่วคราว — ราคาที่ต่ำลงพร้อมวันเริ่มต้นและวันสิ้นสุด เหมือนเซลล์ที่คุณคุ้นเคยจากร้านใหญ่ ๆ",
  "training.lessons.owner-pricing.step2": "ราคาปกติไม่ถูกลบออกไปเลย เมื่อโรลล์แบ็กกำลังดำเนิน แอปจะแสดงราคาลดพร้อมราคาปกติอยู่ข้างกัน และป้ายที่พิมพ์ออกมาจะใช้ราคาลด เพื่อให้ชั้นวางตรงกับแคชเชียร์",
  "training.lessons.owner-pricing.step3": "เมื่อผ่านวันสิ้นสุดไปแล้ว ราคาจะกลับเป็นราคาปกติโดยอัตโนมัติ — ไม่มีอะไรต้องจำ ไม่มีอะไรต้องยกเลิก โรลล์แบ็กที่ยังไม่เริ่มจะบอกวันเริ่มต้นของมันตรงในรายการสินค้า",
  "training.lessons.owner-pricing.step4": "ราคาลดเป็นฟีเจอร์ของแพ็กเกจ Business ใน Essentials ช่องต่าง ๆ จะถูกล็อกไว้ และถ้าธุรกิจลดระดับไป Essentials แล้วกลับมา การตั้งค่าโละสต็อกและโรลล์แบ็กของมันจะยังอยู่ตรงที่เดิม เหมือนที่ทิ้งไว้ทุกอย่าง",
  "training.lessons.owner-pricing.title": "ราคาโละสต็อกและโรลล์แบ็ก (แพ็กเกจ Business)",
  "plansLib.includes.shippingLabels": "ป้ายจัดส่ง 4×6 สำหรับคำสั่งซื้อของลูกค้า — หรือเก็บป้ายของผู้ให้บริการขนส่งของคุณไว้ในไฟล์",
