  "print.printedAt": "พิมพ์เมื่อ {date} เวลา {time}",
  "print.style.previewText": "จิ้งจอกสีน้ำตาลที่รวดเร็วกระโดดข้ามสุนัขที่เกียจคร้าน 1234567890",
  "training.lessons.owner-shipping-labels.step1": "ศูนย์พิมพ์มีสไตล์ป้ายจัดส่งในทั้งสองแพ็กเกจ: เลือกคำสั่งซื้อของลูกค้าแล้วพิมพ์ป้าย 4×6 พร้อมชื่อและที่อยู่ของผู้ซื้อและธุรกิจของคุณในฐานะผู้ส่ง",
  "training.lessons.owner-shipping-labels.step2": "ป้ายนี้เป็นแบบไวท์เลเบลเหมือนเอกสารลูกค้าทุกฉบับ: มีแค่ชื่อธุรกิจของคุณ — ไม่มีชื่อของแอปนี้เลย — ดังนั้นพัสดุจากร้านของคุณจะดูเหมือนมาจาก ร้านของคุณ",
  "training.lessons.owner-shipping-labels.step3": "ที่อยู่ของลูกค้าจะถูกเก็บไว้กับคำสั่งซื้อของพวกเขาเป็นเวลา 90 วันหลังจากคำสั่งซื้อสุดท้าย และฉลากจะเริ่มจากที่อยู่ที่เก็บไว้ของคำสั่งซื้อเมื่อมี ที่อยู่ที่พิมพ์ในเวลาพิมพ์สำหรับฉลากครั้งเดียวจะไม่ถูกบันทึกกลับ ชื่อยังคงกรอกมาจากคำสั่งซื้อเพื่อให้ฉลากตรงกับเอกสาร",
  "training.lessons.owner-shipping-labels.step4": "ป้ายนี้พิมพ์ผ่านการเชื่อมต่อสี่แบบเดียวกันกับป้ายทุกใบ — Bluetooth, Wi-Fi, Ethernet และ USB — และเครื่องพิมพ์ความร้อน 4×6 คือขนาดมาตรฐานของมัน",
  "training.lessons.owner-shipping-labels.step5": "ซื้อค่าไปรษณีย์จากผู้ให้บริการขนส่งแทนหรือ? ในส่วนเดียวกันนี้ คุณสามารถอัปโหลดไฟล์ป้ายของผู้ให้บริการขนส่ง — PDF, PNG หรือ JPG — และมันจะถูกบันทึกไว้บนคำสั่งซื้อตลอดไป: บันทึกของคุณ อยู่ใกล้มือเผื่อมีอะไรเกิดขึ้น มันพิมพ์ด้วยขนาดจริง 4×6 แอปไม่เคยขายค่าไปรษณีย์ ดังนั้นราคาของผู้ให้บริการขนส่งจึงเป็นราคาเดียว — และเป็นราคาที่ถูกต้องเสมอ",
  "training.lessons.owner-shipping-labels.title": "ป้ายจัดส่งสำหรับคำสั่งซื้อของลูกค้า",
  "training.lessons.print-shipping-label.step1": "เมื่อคำสั่งซื้อพร้อมส่ง ให้เปิดศูนย์พิมพ์ เลือกสไตล์ป้ายจัดส่ง แล้วเลือกคำสั่งซื้อของลูกค้า ชื่อของผู้ซื้อจะเติมมาจากคำสั่งซื้อ",
  "training.lessons.print-shipping-label.step2": "ตรวจสอบที่อยู่ที่พัสดุจะไป เมื่อคำสั่งซื้อมีที่อยู่ของลูกค้า — เก็บไว้ 90 วันหลังจากคำสั่งซื้อสุดท้ายของพวกเขา — มันจะกรอกให้คุณ ที่อยู่ที่คุณพิมพ์ในเวลาพิมพ์จะไม่ถูกบันทึกกลับ ดังนั้นตรวจสอบรหัสไปรษณีย์และบรรทัดสุดท้ายอย่างระมัดระวังก่อนพิมพ์",
  "training.lessons.print-shipping-label.step3": "ชื่อธุรกิจของคุณจะพิมพ์อยู่ด้านบนในฐานะผู้ส่ง หากต้องการให้ที่อยู่ของคุณอยู่บนป้ายด้วย ให้พิมพ์ในช่องที่อยู่ผู้ส่ง หากไม่อยากให้แสดงก็เว้นว่างไว้",
  "training.lessons.print-shipping-label.step4": "พิมพ์บนป้าย 4×6 — เครื่องพิมพ์ป้ายความร้อนเป็นตัวเลือกปกติ — หรือบนเครื่องพิมพ์ใดก็ได้ผ่านปุ่มพิมพ์ของเบราว์เซอร์ ติดป้ายให้เรียบเสมอบนพัสดุ ตรงที่ไม่พับข้ามขอบ",
  "training.lessons.print-shipping-label.step5": "หากซื้อค่าไปรษณีย์จากผู้ให้บริการขนส่ง ให้บันทึกไฟล์ป้ายของพวกเขาไว้บนคำสั่งซื้อแทน: อัปโหลด PDF, PNG หรือ JPG ที่ผู้ให้บริการขนส่งให้คุณในส่วนป้ายของผู้ให้บริการขนส่งของคุณ มันจะอยู่บนคำสั่งซื้อเป็นบันทึกของคุณและพิมพ์ด้วยขนาดจริง 4×6 — และป้ายที่อยู่ของแอปเองก็อยู่ที่นั่นเสมอเมื่อคุณต้องการใช้มัน",
  "training.lessons.print-shipping-label.title": "พิมพ์ป้ายจัดส่ง",
