  "pos.stripeTerminal.help": "Stripe Terminal ทำงานบนบัญชี Stripe ของคุณเอง ลงทะเบียนปลายทาง webhook ในแดชบอร์ด Stripe ของคุณสำหรับแอปนี้ จากนั้นวางรหัสบัญชีของคุณและรหัสลับลงนามของปลายทางนั้นที่นี่",
