  "settings.install.desktopSteps": "ในแถบที่อยู่ของเบราว์เซอร์ คลิกไอคอนติดตั้งหากมีแสดง หากไม่มีไอคอน เปิดเมนูเบราว์เซอร์และเลือก “ติดตั้ง Luminous StockHaven” หรือ “เพิ่มไปยังเดสก์ท็อป”",
