  "apiErrors.planLimitNeutral": "เพิ่มสิ่งนี้ตอนนี้ไม่ได้ — โปรดถามเจ้าของธุรกิจ",
  "training.lessons.owner-confidentiality.title": "ข้อมูลของคุณยังคงเป็นความลับ",
  "training.lessons.owner-confidentiality.step1": "Luminous StockHaven เก็บข้อมูลของคุณเป็นความลับจากพนักงานของคุณ การชำระเงิน การทดลองใช้ การสมัครสมาชิก และสถานะการเรียกเก็บเงินของคุณ — และทุกอย่างเกี่ยวกับข้อมูลส่วนตัวของคุณ — เป็นของคุณเพียงผู้เดียว: พนักงานและผู้จัดการจะไม่เห็นสิ่งเหล่านี้เลย ไม่ว่าที่ใดในแอป",
  "training.lessons.owner-confidentiality.step2": "รวมถึงที่เงียบ ๆ ด้วย: ไม่มีการนับถอยหลังการทดลองใช้บนหน้าของพวกเขา ไม่มีส่วนแผนหรือการเรียกเก็บเงินในการตั้งค่าของพวกเขา ไม่มีการเตือนเรื่องการชำระเงิน การตั้งค่าของพวกเขาเป็นเรื่องส่วนตัว — บัญชีของพวกเขาเอง ความปลอดภัย รูปลักษณ์ และภาษา — บวกเฉพาะส่วนเพิ่มเติมที่คุณติ๊กให้พวกเขาเท่านั้น การเรียกเก็บเงินไม่เคยเป็นหนึ่งในช่องติ๊ก",
  "training.lessons.owner-confidentiality.step3": "หากบัญชีถูกหยุดลงสักวันด้วยเหตุผลด้านการเรียกเก็บเงิน พนักงานของคุณจะไม่ได้รับแจ้งเหตุผลเลย พวกเขาจะเห็นเพียงการหยุดที่เรียบง่ายและเป็นกลาง — การเปลี่ยนแปลงถูกปิดอยู่ตอนนี้ — เพื่อให้คุณอธิบายให้ทีมของคุณฟังด้วยคำพูดของคุณเอง",
  "training.lessons.owner-confidentiality.step4": "และหากคุณพบเห็นสิ่งใดที่แสดงต่อพนักงานของคุณที่ไม่ควรแสดง — การรั่วไหลใด ๆ — โปรดเปิดการตั้งค่าและแตะรายงานปัญหาเพื่อแจ้งให้เราทราบ เพื่อที่เราจะได้แก้ไขโดยเร็วที่สุด",
  "staffLib.perm.settingsContactDetails": "รายละเอียดการติดต่อของธุรกิจ (ที่อยู่และโทรศัพท์)",
