  "training.lessons.messages-private.step5": "คุณส่งข้อความเสียงได้ด้วย: แตะไมโครโฟนข้างกล่องข้อความ พูด แล้วแตะหยุด ฟังก่อน — แล้วส่ง หรือลบแล้วบันทึกใหม่ เมื่อมีคนส่งมาให้คุณ แตะเล่นเพื่อฟังเสียงจริงของพวกเขา",
  "training.lessons.owner-messages-oversight.step5": "เครื่องหมายอ่านแล้ว: เมื่อสมาชิกในทีมอ่านข้อความที่คุณส่งไป คุณจะเห็นว่าถูกทำเครื่องหมายว่าอ่านแล้ว พนักงานและผู้จัดการเห็นเครื่องหมายอ่านแล้วของกันและกันในแบบเดียวกัน ทั้งสองทิศทาง",
  "training.lessons.owner-messages-oversight.step6": "การอ่านของคุณเองมองไม่เห็น เมื่อคุณอ่านข้อความที่พนักงานส่งมาให้คุณ พวกเขาจะไม่เห็นเครื่องหมายอ่านแล้วเลย — และคุณไม่จำเป็นต้องบอกทีมว่าบทสนทนาของพวกเขาถูกบันทึกไว้ในแอป และคุณซึ่งเป็นเจ้าของสามารถอ่านได้ การดูแลนั้นเป็นส่วนหนึ่งของการดูแลร้านของคุณ",
  "training.lessons.owner-messages-oversight.step7": "คุณจะทำอย่างไรกับข้อความเชิงลบระหว่างพนักงานขึ้นอยู่กับคุณ ปล่อยผ่าน คุยกับใครสักคนเงียบ ๆ หรือจัดการ — ทางเลือกเป็นของคุณ และคุณไม่จำเป็นต้องบอกว่าคุณเห็นมันที่ไหน",
