  "apiErrors.businessPoliciesOwnerOnly": "มีเพียงเจ้าของเท่านั้นที่สามารถเปลี่ยนนโยบายและข้อกำหนดของร้านนี้ได้",
  "apiErrors.policyFileInvalid": "ส่งไฟล์ PDF, ข้อความ, Word หรือ OpenDocument ที่มีขนาดต่ำกว่า 2 MB",
  "apiErrors.policyTextTooLong": "เอกสารนั้นยาวเกินกว่าจะพิมพ์ที่นี่ คุณสามารถอัปโหลดเป็นไฟล์แทนได้",
  "training.lessons.owner-store-policies.title": "นโยบายและข้อกำหนดของร้านของคุณ",
  "training.lessons.owner-store-policies.step1": "เปิด การตั้งค่า แล้วค้นหาการ์ด นโยบายและข้อกำหนดของร้าน การ์ดนี้มีเอกสารสองฉบับ: นโยบายร้านค้าของคุณ — กฎประจำบ้านสำหรับร้านของคุณ — และข้อกำหนดและเงื่อนไขของคุณ",
  "training.lessons.owner-store-policies.step2": "เอกสารแต่ละฉบับสามารถพิมพ์ลงไปตรงนั้นได้เลย หรืออัปโหลดเป็นไฟล์ (PDF, ข้อความ, Word หรือ OpenDocument ขนาดไม่เกิน 2 MB) อย่างใดอย่างหนึ่งเท่านั้น: การบันทึกข้อความจะแทนที่ไฟล์ และการอัปโหลดไฟล์จะแทนที่ข้อความ การลบเอกสารจะทำให้เอกสารว่างเปล่า",
  "training.lessons.owner-store-policies.step3": "ทีมของคุณจะเห็นเอกสารทั้งสองฉบับหนึ่งครั้ง บนหน้ายินดีต้อนรับเมื่อพวกเขาเริ่มต้นครั้งแรก และสามารถอ่านได้ทุกเมื่อใน การตั้งค่า ของพวกเขา สำหรับทีมของคุณ เอกสารเหล่านี้อ่านได้อย่างเดียว — มีเพียงคุณเท่านั้นที่เขียนหรือเปลี่ยนได้",
  "training.lessons.owner-store-policies.step4": "แต่ละธุรกิจเก็บเอกสารของตัวเอง: สิ่งที่คุณเขียนที่นี่เป็นของร้านนี้เท่านั้นและจะไม่ปรากฏในธุรกิจอื่นเลย ข้อกำหนดและนโยบายของ Luminous StockHaven เองอยู่ใน การตั้งค่า ข้างๆ ของคุณ และทุกคนก็อ่านได้เช่นกัน",
  "training.lessons.welcome-basics.step5": "นโยบายและข้อกำหนดของร้านของคุณจะแสดงหนึ่งครั้งบนหน้ายินดีต้อนรับของคุณ และอยู่ใน การตั้งค่า ที่ซึ่งคุณสามารถอ่านได้ทุกเมื่อ",
