  "apiErrors.reorderChangeReserved": "เฉพาะเจ้าของ หรือสมาชิกทีมที่เจ้าของอนุญาตให้เปลี่ยนจุดสั่งซื้อซ้ำเท่านั้น ที่สามารถเปลี่ยนจุดสั่งซื้อซ้ำได้",
  "apiErrors.alertsViewReserved": "เฉพาะเจ้าของ หรือสมาชิกทีมที่เจ้าของอนุญาตให้ดูการแจ้งเตือนสต็อกต่ำเท่านั้น ที่สามารถดูการแจ้งเตือนสต็อกต่ำได้",
