  "settings.policyQuiz.expectedHint": "คำตอบที่คุณคาดหวัง ในคำพูดของคุณเอง คำตอบที่ตรงกันเกือบทุกคำจะนับว่าถูกต้องทันที ส่วนที่เหลือจะมาถึงคุณเพื่อให้คุณดู",
  "settings.policyQuiz.hint": "เขียนคำถามเกี่ยวกับเอกสารนี้สำหรับทีมของคุณ บุคคลจะตอบคำถามเหล่านั้นใน การฝึกอบรม เมื่อคุณติ๊กการฝึกอบรมนี้ให้พวกเขาในบันทึกพนักงานของพวกเขา ไม่มีการจำกัดจำนวนคำถามที่คุณเขียน",
