  "training.lessons.your-profile-photo.title": "รูปโปรไฟล์ของคุณ",
  "training.lessons.your-profile-photo.step1": "รูปของคุณจะปรากฏข้างชื่อของคุณที่ด้านบนของแอป ในหน้าพนักงาน และข้างข้อความของคุณ — เมื่อเจ้าของอนุมัติแล้ว จนกว่าจะถึงตอนนั้น จะแสดงเพียงตัวอักษรย่อของชื่อคุณเท่านั้น",
  "training.lessons.your-profile-photo.step2": "เปิดการตั้งค่าและค้นหารูปโปรไฟล์ของคุณ เลือกรูปภาพของตัวเองและส่งไป รูปจะถูกส่งให้เจ้าของอนุมัติ — จะไม่ปรากฏที่ใดในขณะที่รอ",
  "training.lessons.your-profile-photo.step3": "เมื่อเจ้าของอนุมัติ กระดิ่งของคุณจะดังและรูปของคุณจะเริ่มแสดง หากไม่ได้รับการอนุมัติ ให้เลือกรูปภาพอื่นและส่งรูปนั้นแทน",
  "training.lessons.your-profile-photo.step4": "การเปลี่ยนรูปภาพทำงานในลักษณะเดียวกัน: รูปใหม่จะรอการอนุมัติ และรูปปัจจุบันของคุณจะยังคงอยู่จนกว่ารูปใหม่จะได้รับการอนุมัติ หากการเปลี่ยนแปลงไม่ได้รับการอนุมัติ คุณจะยังคงมีรูปอื่นอยู่",
  "training.lessons.owner-profile-photos.title": "รูปโปรไฟล์และชื่อของคุณ",
  "training.lessons.owner-profile-photos.step1": "รูปของทุกคนจะแสดงข้างชื่อของพวกเขาที่ด้านบนของแอป ในหน้าพนักงานของคุณ และข้างข้อความของพวกเขา รูปภาพของสมาชิกทีมจะไม่ปรากฏที่ใดจนกว่าคุณจะอนุมัติ — การอนุมัติเป็นของคุณแต่เพียงผู้เดียว และไม่มีใครสามารถอนุมัติรูปของตัวเองได้",
  "training.lessons.owner-profile-photos.step2": "เมื่อมีคนส่งรูปภาพมา กระดิ่งของคุณจะดัง เปิดหน้าพนักงานเพื่อดู จากนั้นเลือกอนุมัติหรือไม่อนุมัติ หากคุณไม่อนุมัติ บุคคลนั้นจะได้รับแจ้งให้เลือกรูปภาพอื่น",
  "training.lessons.owner-profile-photos.step3": "หากบุคคลหนึ่งเปลี่ยนรูปภาพ รูปใหม่จะรอการอนุมัติจากคุณในลักษณะเดียวกัน รูปปัจจุบันของพวกเขาจะยังคงอยู่ในขณะที่รอ — และจะยังคงอยู่หากคุณไม่อนุมัติการเปลี่ยนแปลง",
  "training.lessons.owner-profile-photos.step4": "รูปของคุณเองไม่ต้องรอการอนุมัติ: ตั้งค่าได้ในการตั้งค่า ภายใต้รูปโปรไฟล์ของคุณ การ์ดเดียวกันนี้มีชื่อของคุณด้วย — ชื่อที่คุณตั้งไว้ที่นั่นจะแทนที่คำว่าเจ้าของในทุกที่ที่ทีมของคุณเห็น ทั้งในแอปและในข้อความ",
