  "training.lessons.mgr-clock-callin.title": "การเรียกเข้าทำงานและการแก้ไขนาฬิกา",
  "training.lessons.mgr-clock-callin.step1": "เจ้าของสามารถให้เครื่องหมายหนึ่งอย่างแก่ผู้จัดการ — การเรียกเข้าทำงานและการแก้ไขนาฬิกา ด้วยเครื่องหมายนี้ คุณสามารถเปิดหน้าต่างการเรียกเข้าทำงานให้สมาชิกพนักงานและแก้ไขบันทึกเวลาจากหน้าพนักงานได้",
  "training.lessons.mgr-clock-callin.step2": "หน้าต่างการเรียกเข้าทำงานให้บุคคลหนึ่งเข้าสู่ระบบและลงเวลาเข้าได้เมื่อไม่มีกะครอบคลุมเขา เปิดได้จากหน้าพนักงาน บนการ์ดการเรียกเข้าทำงานและการลืมลงเวลาออก",
  "training.lessons.mgr-clock-callin.step3": "หน้าต่างจะเปิดอยู่จนกว่าคนนั้นจะลงเวลาออก — จากนั้นเป็นช่วงผ่อนผัน 10 นาทีตามปกติก่อนออกจากระบบ — หรือจนกว่าคุณหรือเจ้าของจะปิดก่อน ไม่มีอะไรปิดมันเอง",
  "training.lessons.mgr-clock-callin.step4": "เมื่อใครบางคนลืมลงเวลาออก บันทึกของเขาจะถูกทำเครื่องหมายในหน้าพนักงานและในบัญชีเงินเดือนทันทีที่กะที่กำหนดไว้สิ้นสุดลง และคุณกับเจ้าของจะได้รับแจ้ง บันทึกจะนับต่อไปจนกว่าจะได้รับการแก้ไข",
  "training.lessons.mgr-clock-callin.step5": "แก้ไขบันทึกจากหน้าพนักงาน: ตั้งเวลาเข้า เวลาออก และเวลาพัก ผู้จัดการแก้ไขได้เฉพาะบันทึกของพนักงานเท่านั้น — บันทึกของผู้จัดการเองเจ้าของเป็นผู้แก้ไข",
  "staffLib.perm.staffDocuments": "เอกสารของพนักงาน",
  "staffLib.area.documentsAccess": "เอกสารของพนักงาน",
  "staff.memberDialog.documentsAccessHint": "สำหรับผู้จัดการเท่านั้น — ด้วยเครื่องหมายนี้ ผู้จัดการคนนี้สามารถเปิดไฟล์เอกสารของสมาชิกพนักงานได้: เอกสารที่เก็บไว้สำหรับแต่ละคน เช่น แบบฟอร์ม W-4 ใบสมัครงาน และสำเนาบัตรประจำตัว จะมีการขอคำยืนยันจากคุณก่อน — ไฟล์เหล่านี้มีหมายเลขประกันสังคมและวันเกิด เครื่องหมายนี้ไม่ทำอะไรสำหรับพนักงาน",
