  "plansLib.businessIncludes.restaurantDaily": "เครื่องมือประจำวันของร้านอาหาร — บันทึกอุณหภูมิ กระดานรายการที่หมด ใบเตรียมอาหาร การวิเคราะห์เมนู ผลต่าง และการส่งออกบัญชี",
